//! The framing planner (road map "creator-jobs" VR2a1, spec §11 VR-20,
//! VR-22, VR-23): a clip's analysed subjects in, a [`FramingPath`] out — a
//! similarity per instant from the canvas the clip was authored for (`Ws ×
//! Hs`) to the current one (`W × H`). Pure; nothing here edits.
//! `edit_reframe.rs`'s op writes the path as the clip's base and actions
//! (`reframe_cover.rs`).
//!
//! **The frames.** A box is 0…1 of the upright picture from its top-left. Its
//! point `(bx, by)` is `u = (bx·mw − mw/2, by·mh − mh/2)` px from the
//! UNCROPPED centre (`mw × mh` the media's displayed size), and lands on the
//! source canvas at `anchor + s·u` — `edit_zoom.rs`'s (★) at θ = 0, with
//! `anchor` and `s` the clip's base `video`. A crop moves only the
//! picture's extent, the cropped rect `anchor + s·(c ± (cw/2, ch/2))`, so
//! the analysis cache never depends on it.
//!
//! **The window.** The part of the source canvas the target shows: `W/k ×
//! H/k`, where `k·s` is `zoom ×` the fill scale of the cropped picture on
//! the target (`Project::fill_scale`), at most `SCALE_MAX`. A key is
//! `(k, dx, dy)` with `dx = k·(Ws/2 − wc.x)`, `dy = k·(Hs/2 − wc.y)` for a
//! window centred at `wc`; composed into a placement as `scale′ = k·scale,
//! x′ = k·x + dx, y′ = k·y + dy` (VR-3, VR-27). Every `wc` is clamped so the
//! window lies inside the cropped rect (VR-7's covering key).
//!
//! **The placement in force** (VR-27 (a)). A clip with actions moves its
//! picture under the window: a sample's point is (★) through the clip's
//! evaluated placement at its own tick (`Frame.placed`), and the rect the
//! window is clamped into is the COMMON one — the cropped rects of the base
//! and of the placement at every action's end, intersected — with `k`
//! raised until the window fits it, held so `k·s` stays at most `SCALE_MAX`
//! at every one of those placements. A clip with no actions is VR2a2's.
//!
//! **The path.** VR-21 (`reframe_tracks.rs`) chooses a subject per sample;
//! VR-22 composes the window on it; `reframe_path.rs` writes the keys —
//! VR-23's moves only when the median-filtered subject leaves a dead zone,
//! each a hold key and an eased key, and VR-24's hard cuts, loss, return and
//! two people — snapped to the canvas's frames. Where there is nothing to
//! follow the path holds a `where_empty` state ([`WhereEmpty`]): the window on
//! the cropped centre, or the whole cropped picture fitted (`edit_zoom.rs`'s
//! solves at θ = 0), which [`fixed_framing`] also answers for `follow`
//! `center` and `fit` (VR2a2).

use crate::clip_source_time::{clip_time_of_source, in_played_window, Round};
use crate::edit_zoom::{zoom_offset, zoom_scale, ZoomFit, ZoomRegion};
use crate::model::{Clip, Curve, MediaKind, Project, Source};
use crate::props_check::SCALE_MAX;
use crate::reframe_path::write_keys;
pub use crate::reframe_subjects::Subjects;
pub use crate::reframe_tracks::{
    choose_subject, Chosen, Follow, SubjectBox, SubjectKind, SubjectSample,
};
use crate::time::Ticks;
use serde::{Deserialize, Serialize};

/// What a framing shows where there is nothing to follow (spec §11 VR-24
/// (h)): the whole cropped picture fitted, or the follow window on its
/// centre.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum WhereEmpty {
    #[default]
    Fit,
    Center,
}

/// What to follow, how tight (1…4 × fill), the canvas the clip was
/// authored for, and what to show with nothing to follow.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct FramingRequest {
    pub follow: Follow,
    pub zoom: f64,
    pub from_width: u32,
    pub from_height: u32,
    pub where_empty: WhereEmpty,
}

/// VR-22's and VR-23's numbers: the dead zone as shares of the window's
/// width and height, the speed in window widths a second, the headroom as a
/// share of the window's height.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct FramingTuning {
    pub dead_zone_width: f64,
    pub dead_zone_height: f64,
    pub speed: f64,
    pub headroom: f64,
}

/// VR-S2's verdict (spec §11 VR-23): the dead zone 0.15 of the window's
/// width and 0.12 of its height, 0.8 window widths a second, the headroom
/// 0.38 (which the canned run could not measure, so it stays the first
/// number).
pub const FRAMING_TUNING: FramingTuning = FramingTuning {
    dead_zone_width: 0.15,
    dead_zone_height: 0.12,
    speed: 0.8,
    headroom: 0.38,
};

/// A person box's top sits this share of the window's height below its top.
const PERSON_TOP: f64 = 0.12;

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct FramingKey {
    pub t: Ticks,
    pub scale: f64,
    pub x: f64,
    pub y: f64,
    pub curve: Curve,
}

#[derive(Debug, Clone, PartialEq)]
pub struct FramingPath {
    pub keys: Vec<FramingKey>,
    /// Some key holds the `fit` state (VR-24 (h)): the picture shows the
    /// canvas around it, so VR-25's backdrop has a span to fill.
    pub shows_fit: bool,
    /// Each hard cut's key time `c` whose key differs from the hold at
    /// `c − frame` (VR-24 (b)), ascending: `reframe_compose.rs` splits the
    /// action a cut lands in (VR-27 (d)).
    pub cuts: Vec<Ticks>,
}

pub(crate) type Point = (f64, f64);

/// The geometry one plan reads: the clip's placement on the source canvas,
/// the common cropped rect (VR-27 (a)), and the window.
pub(crate) struct Frame {
    pub(crate) anchor: Point,
    pub(crate) s: f64,
    pub(crate) media: Point,
    pub(crate) rect: (Point, Point),
    /// The placement in force at each in-clip sample tick, `(tick, scale, x,
    /// y)`, sorted; empty for a clip with no actions, whose points read the
    /// base (VR-27 (a)).
    pub(crate) placed: Vec<(Ticks, f64, f64, f64)>,
    pub(crate) k: f64,
    pub(crate) window: Point,
    pub(crate) half_source: Point,
    /// The `fit` state as a key of F: `(k, dx, dy)` (VR-24 (h)).
    pub(crate) fit: (f64, f64, f64),
}

impl Frame {
    /// The geometry of `clip`, sized through [`Project::source_size`]; `None`
    /// for no size, a base rotation other than 0, a zoom outside 1…4, a zero
    /// source canvas, or a crop or scale that leaves no picture.
    pub(crate) fn of(project: &Project, clip: &Clip, request: &FramingRequest) -> Option<Frame> {
        let video = clip.video.clone().unwrap_or_default();
        if video.rotation != 0.0 {
            return None;
        }
        let (mw, mh) = project.source_size(clip)?;
        let zoom = request.zoom;
        let (ws, hs) = (
            f64::from(request.from_width),
            f64::from(request.from_height),
        );
        if mw <= 0.0 || mh <= 0.0 || !(1.0..=4.0).contains(&zoom) || ws <= 0.0 || hs <= 0.0 {
            return None;
        }
        let crop = video.crop;
        let (cw, ch) = (mw - crop.l - crop.r, mh - crop.t - crop.b);
        let s = video.scale;
        if !(cw > 0.0 && ch > 0.0 && s.is_finite() && s > 0.0) {
            return None;
        }
        let anchor = (ws / 2.0 + video.x, hs / 2.0 + video.y);
        let c = ((crop.l - crop.r) / 2.0, (crop.t - crop.b) / 2.0);
        let rect_of = |s: f64, anchor: Point| {
            (
                (
                    anchor.0 + s * (c.0 - cw / 2.0),
                    anchor.1 + s * (c.1 - ch / 2.0),
                ),
                (
                    anchor.0 + s * (c.0 + cw / 2.0),
                    anchor.1 + s * (c.1 + ch / 2.0),
                ),
            )
        };
        let base_rect = rect_of(s, anchor);
        let (w, h) = (
            f64::from(project.canvas.width),
            f64::from(project.canvas.height),
        );
        // VR-27 (a): the common rect over the base and every action's end,
        // and the largest scale among them.
        let (mut rect, mut s_max) = (base_rect, s);
        for a in &clip.actions {
            let p = project
                .evaluate_clip(clip, a.start.saturating_add(a.duration))
                .video;
            if !(p.scale.is_finite() && p.scale > 0.0 && p.x.is_finite() && p.y.is_finite()) {
                continue;
            }
            let ((x0, y0), (x1, y1)) = rect_of(p.scale, (ws / 2.0 + p.x, hs / 2.0 + p.y));
            rect = (
                (rect.0 .0.max(x0), rect.0 .1.max(y0)),
                (rect.1 .0.min(x1), rect.1 .1.min(y1)),
            );
            s_max = s_max.max(p.scale);
        }
        let ((x0, y0), (x1, y1)) = rect;
        if !(x0 < x1 && y0 < y1) {
            rect = base_rect;
        }
        let mut k = (zoom * project.fill_scale(cw, ch)).min(SCALE_MAX) / s;
        // Only a smaller rect raises `k`, so an action-free clip's `k` is
        // VR2a2's to the bit.
        let raised = rect != base_rect;
        if raised {
            let ((x0, y0), (x1, y1)) = rect;
            k = k.max(w / (x1 - x0)).max(h / (y1 - y0));
        }
        if raised || s_max > s {
            k = k.min(SCALE_MAX / s_max);
        }
        // Fit: the cropped picture fitted at θ = 0 by `edit_zoom.rs`'s two
        // solves, written as F so it composes like any key.
        let whole = ZoomRegion {
            x: 0.0,
            y: 0.0,
            width: cw,
            height: ch,
        };
        let fit_scale = zoom_scale((w, h), &whole, ZoomFit::Fit, 0.0);
        let (fx, fy) = zoom_offset(&video, &whole, fit_scale);
        let kf = fit_scale / s;
        Some(Frame {
            anchor,
            s,
            media: (mw, mh),
            rect,
            k,
            window: (w / k, h / k),
            half_source: (ws / 2.0, hs / 2.0),
            fit: (kf, fx - kf * video.x, fy - kf * video.y),
            placed: Vec::new(),
        })
    }

    /// A box point (0…1 of the picture) on the source canvas, through the
    /// placement in force at clip tick `t` (VR-27 (a)); the base's when
    /// none was read there.
    pub(crate) fn point(&self, t: Ticks, bx: f64, by: f64) -> Point {
        let (mw, mh) = self.media;
        let (s, anchor) = match self.placed.binary_search_by_key(&t, |p| p.0) {
            Ok(i) => {
                let (_, s, x, y) = self.placed[i];
                (s, (self.half_source.0 + x, self.half_source.1 + y))
            }
            Err(_) => (self.s, self.anchor),
        };
        (
            anchor.0 + s * (bx * mw - mw / 2.0),
            anchor.1 + s * (by * mh - mh / 2.0),
        )
    }

    /// `wc` moved so the window lies inside the cropped rect (its centre
    /// when the window is the larger).
    pub(crate) fn clamp(&self, wc: Point) -> Point {
        let ((x0, y0), (x1, y1)) = self.rect;
        let axis = |v: f64, lo: f64, hi: f64| {
            if lo > hi {
                (lo + hi) / 2.0
            } else {
                v.clamp(lo, hi)
            }
        };
        (
            axis(wc.0, x0 + self.window.0 / 2.0, x1 - self.window.0 / 2.0),
            axis(wc.1, y0 + self.window.1 / 2.0, y1 - self.window.1 / 2.0),
        )
    }

    /// The cropped rect's centre.
    pub(crate) fn centre(&self) -> Point {
        let ((x0, y0), (x1, y1)) = self.rect;
        ((x0 + x1) / 2.0, (y0 + y1) / 2.0)
    }

    /// The `fit` state's key at `t`.
    pub(crate) fn fit_key(&self, t: Ticks, curve: Curve) -> FramingKey {
        let (scale, x, y) = self.fit;
        FramingKey {
            t,
            scale,
            x,
            y,
            curve,
        }
    }

    pub(crate) fn key(&self, t: Ticks, wc: Point, curve: Curve) -> FramingKey {
        FramingKey {
            t,
            scale: self.k,
            x: self.k * (self.half_source.0 - wc.0),
            y: self.k * (self.half_source.1 - wc.1),
            curve,
        }
    }

    /// VR-22: the subject point of a kind's box at clip tick `t`, and the
    /// window centre's offset from it.
    pub(crate) fn subject(
        &self,
        t: Ticks,
        kind: SubjectKind,
        b: &SubjectBox,
        headroom: f64,
    ) -> (Point, Point) {
        let (w, h) = self.window;
        match kind {
            SubjectKind::Face => {
                let lift = if h > w { h / 2.0 - headroom * h } else { 0.0 };
                (self.point(t, b.x + b.w / 2.0, b.y + b.h / 2.0), (0.0, lift))
            }
            SubjectKind::Person => (
                self.point(t, b.x + b.w / 2.0, b.y),
                (0.0, h / 2.0 - PERSON_TOP * h),
            ),
            SubjectKind::Salient => (self.point(t, b.x + b.w / 2.0, b.y + b.h / 2.0), (0.0, 0.0)),
        }
    }
}

/// The samples and shots in clip time (VR-20): kept when in the played
/// window, ascending, one sample per clip tick (the earliest media tick's),
/// one shot per tick, a cut at 0 or at or past the end dropped.
pub(crate) fn in_clip_time(
    clip: &Clip,
    project: &Project,
    subjects: &Subjects,
) -> (Vec<SubjectSample>, Vec<Ticks>) {
    let Source::Media { media, .. } = clip.source else {
        return (Vec::new(), Vec::new());
    };
    let Some(media) = project.media(media) else {
        return (Vec::new(), Vec::new());
    };
    let at = |t: Ticks| {
        in_played_window(clip, media, t)
            .then(|| clip_time_of_source(clip, media, t, Round::Down))
            .flatten()
    };
    let mut samples: Vec<(Ticks, Ticks, &SubjectSample)> = subjects
        .samples
        .iter()
        .filter_map(|s| at(s.t).map(|c| (c, s.t, s)))
        .collect();
    samples.sort_by_key(|&(c, m, _)| (c, m));
    samples.dedup_by_key(|&mut (c, _, _)| c);
    // A shot rounds UP (VR-24 (a)): its clip tick is the first that shows
    // the new shot, where a sample's rounds down.
    let at_up = |t: Ticks| {
        in_played_window(clip, media, t)
            .then(|| clip_time_of_source(clip, media, t, Round::Up))
            .flatten()
    };
    let mut shots: Vec<Ticks> = subjects
        .shots
        .iter()
        .filter_map(|&t| at_up(t))
        .filter(|&c| c > 0 && c < clip.duration)
        .collect();
    shots.sort_unstable();
    shots.dedup();
    let samples = samples
        .into_iter()
        .map(|(c, _, s)| SubjectSample { t: c, ..s.clone() })
        .collect();
    (samples, shots)
}

/// The planner (spec §11 VR-20…VR-24). `None` for: no such clip, not a
/// media clip of a video media, a base rotation other than 0, a media with
/// no size, a crop or scale that leaves no picture, a zoom outside 1…4, or a
/// zero `from_width`/`from_height`. VR2a2 refuses each by name before
/// calling.
pub fn plan_framing(
    project: &Project,
    clip: u32,
    subjects: &Subjects,
    request: &FramingRequest,
    tuning: &FramingTuning,
) -> Option<FramingPath> {
    let clip = project.clip(clip)?;
    let Source::Media { media, .. } = clip.source else {
        return None;
    };
    let media = project.media(media)?;
    if media.kind != MediaKind::Video || !media.has_video {
        return None;
    }
    let mut frame = Frame::of(project, clip, request)?;
    let (samples, shots) = in_clip_time(clip, project, subjects);
    if !clip.actions.is_empty() {
        frame.placed = samples
            .iter()
            .map(|s| {
                let p = project.evaluate_clip(clip, s.t).video;
                (s.t, p.scale, p.x, p.y)
            })
            .collect();
    }
    let chosen = choose_subject(&samples, &shots, request.follow);
    Some(write_keys(
        &frame,
        &chosen,
        &shots,
        clip.duration,
        project.canvas.fps,
        request,
        tuning,
    ))
}

/// One key at 0 holding a `where_empty` state for the whole clip (spec §11
/// VR-24 (h), VR-26): `follow` `center` (the window at fill × `zoom` on the
/// cropped centre) and `fit` (the cropped picture fitted; `zoom` unread).
/// `None` for no such clip, no size, a base rotation other than 0, a zoom
/// outside 1…4, or a crop or scale that leaves no picture. Offsets are
/// measured from the canvas's own centre, so the source canvas is the
/// current one.
pub fn fixed_framing(
    project: &Project,
    clip: u32,
    state: WhereEmpty,
    zoom: f64,
) -> Option<FramingPath> {
    let clip = project.clip(clip)?;
    let request = FramingRequest {
        follow: Follow::Subject,
        zoom,
        from_width: project.canvas.width,
        from_height: project.canvas.height,
        where_empty: state,
    };
    let frame = Frame::of(project, clip, &request)?;
    let key = match state {
        WhereEmpty::Center => frame.key(0, frame.centre(), Curve::Linear),
        WhereEmpty::Fit => frame.fit_key(0, Curve::Linear),
    };
    Some(FramingPath {
        keys: vec![key],
        shows_fit: state == WhereEmpty::Fit,
        cuts: Vec::new(),
    })
}
//! `reframe_clip`'s `subjects` argument (road map "creator-jobs" VR2a2,
//! spec §11 VR-26): the analysed samples and shots of a clip's media, in
//! MEDIA source ticks of the forward file, read strictly and checked. A pure
//! move out of `reframe.rs` (the type) and `edit_reframe.rs` (its reader and
//! check), so the cursor's points (VR5) land beside them.
//!
//! **The cursor** (VR5, spec §11 VR-50): `cursor`, optional, is a recorded
//! pointer's points `{t, x, y, click?, typing?}` — `t` in forward-media
//! source ticks, `x`, `y` 0…1 of the upright picture from its top-left
//! (CJ-22), `click` a down click and `typing` inside a typing stretch, both
//! false when absent — which `follow: cursor` frames on
//! (`reframe_cursor.rs`). A face follow never reads it (VR-51).
//!
//! **The speaker's facts** (VR6a, spec §11 VR-60 (b)): a face box's
//! `mouth`, optional, is its mouth's gap over its width (SW-81's opening),
//! and `turns`, optional, are who speaks when — `{from, to, mic}` in
//! CONTAINER timeline ticks, `mic` a clip id of `reframe_clip`'s `mics` —
//! which `follow: speaker` frames on (`reframe_speaker.rs`). Both are the
//! tool's to fill; no other follow reads them.
//!
//! **`subjects` is read strictly**, as `ZoomRegion` is: an object at every
//! level, a stray, missing or wrong-typed member named by its path. Its
//! VALUES are refusals (VR-26 (8)): a cached sample is a fact, not a typo.

use serde::de::{self, Deserializer};
use serde::{Deserialize, Serialize};
use serde_json::Value;

use crate::edit_reframe::{MAX_SUBJECT_BOXES, MAX_SUBJECT_SAMPLES};
use crate::export::describe;
use crate::time::Ticks;

/// One box, 0…1 of the upright picture from its top-left (CJ-22, VR-10),
/// with its confidence.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SubjectBox {
    pub x: f64,
    pub y: f64,
    pub w: f64,
    pub h: f64,
    pub c: f64,
    /// A face's mouth gap over its width (VR-60 (b)); absent when unread.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mouth: Option<f64>,
}

/// One analysed instant: its faces, people and salient regions.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SubjectSample {
    pub t: Ticks,
    #[serde(default)]
    pub faces: Vec<SubjectBox>,
    #[serde(default)]
    pub people: Vec<SubjectBox>,
    #[serde(default)]
    pub salient: Vec<SubjectBox>,
}

/// One recorded cursor point (spec §11 VR-50): media source ticks of the
/// forward file, 0…1 of the upright picture.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct CursorPoint {
    pub t: Ticks,
    pub x: f64,
    pub y: f64,
    #[serde(default)]
    pub click: bool,
    #[serde(default)]
    pub typing: bool,
}

/// One speaker turn (VR-60 (b)): `[from, to)` in container timeline ticks,
/// `mic` the clip id of the microphone speaking.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Turn {
    pub from: Ticks,
    pub to: Ticks,
    pub mic: u32,
}

/// A clip's analysed subjects in MEDIA source ticks of the forward file.
/// `reframe_clip`'s `subjects` argument; its strict `Deserialize` is below.
#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct Subjects {
    pub samples: Vec<SubjectSample>,
    pub shots: Vec<Ticks>,
    /// The recorded cursor (VR-50), empty when absent.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub cursor: Vec<CursorPoint>,
    /// Who speaks when (VR-60 (b)), empty when absent.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub turns: Vec<Turn>,
}

impl<'de> Deserialize<'de> for Subjects {
    /// `{samples: [{t, faces?, people?, salient?: [{x, y, w, h, c}]}], shots,
    /// cursor?: [{t, x, y, click?, typing?}], turns?: [{from, to, mic}]}`.
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        #[derive(Deserialize)]
        #[serde(deny_unknown_fields)]
        struct SubjectsIn {
            samples: Vec<SubjectSample>,
            shots: Vec<Ticks>,
            #[serde(default)]
            cursor: Vec<CursorPoint>,
            #[serde(default)]
            turns: Vec<Turn>,
        }
        let bad =
            |at: &str, what: String| de::Error::custom(format!("bad value at \"{at}\": {what}"));
        let value = Value::deserialize(deserializer)?;
        if !value.is_object() {
            return Err(de::Error::custom(format!(
                "expected an object, not {}",
                describe(&value)
            )));
        }
        // serde would read a list into a struct member by member.
        let samples = value["samples"]
            .as_array()
            .into_iter()
            .flatten()
            .enumerate();
        for (i, sample) in samples {
            let boxes = ["faces", "people", "salient"].into_iter().flat_map(|kind| {
                let list = sample[kind].as_array().into_iter().flatten().enumerate();
                list.map(move |(j, b)| (format!("subjects.samples[{i}].{kind}[{j}]"), b))
            });
            let here = std::iter::once((format!("subjects.samples[{i}]"), sample));
            if let Some((at, v)) = here.chain(boxes).find(|(_, v)| !v.is_object()) {
                return Err(bad(&at, format!("expected an object, not {}", describe(v))));
            }
        }
        for (list, name) in [(&value["cursor"], "cursor"), (&value["turns"], "turns")] {
            let points = list.as_array().into_iter().flatten().enumerate();
            for (i, point) in points {
                if point.is_object() {
                    continue;
                }
                let at = format!("subjects.{name}[{i}]");
                return Err(bad(
                    &at,
                    format!("expected an object, not {}", describe(point)),
                ));
            }
        }
        let read: SubjectsIn = serde_path_to_error::deserialize(value).map_err(|e| {
            let at = crate::patch::path_under("subjects", &e.path().to_string());
            bad(&at, e.inner().to_string())
        })?;
        Ok(Subjects {
            samples: read.samples,
            shots: read.shots,
            cursor: read.cursor,
            turns: read.turns,
        })
    }
}

/// VR-26 (8): the samples' count, order, box counts and values (a `mouth`
/// only on a face, finite and at least 0, VR-60 (d)); then the cursor's
/// count, order and values (VR-50); then the turns'.
pub(crate) fn check_subjects(subjects: &Subjects) -> Result<(), String> {
    let n = subjects.samples.len();
    if n > MAX_SUBJECT_SAMPLES {
        return Err(format!(
            "subjects holds {n} samples, more than {MAX_SUBJECT_SAMPLES}"
        ));
    }
    let mut previous: Option<Ticks> = None;
    for (i, sample) in subjects.samples.iter().enumerate() {
        if let Some(p) = previous.filter(|&p| sample.t <= p) {
            return Err(format!(
                "subjects sample {i} is at {}, not after the one before it ({p}); sample \
                 times must be strictly increasing",
                sample.t
            ));
        }
        previous = Some(sample.t);
        for (kind, list) in [
            ("faces", &sample.faces),
            ("people", &sample.people),
            ("salient", &sample.salient),
        ] {
            if list.len() > MAX_SUBJECT_BOXES {
                return Err(format!(
                    "subjects sample {i} holds {} {kind}, more than {MAX_SUBJECT_BOXES}",
                    list.len()
                ));
            }
            for (j, b) in list.iter().enumerate() {
                for (key, v) in [("x", b.x), ("y", b.y), ("w", b.w), ("h", b.h), ("c", b.c)] {
                    if !(0.0..=1.0).contains(&v) {
                        return Err(format!(
                            "subjects sample {i}'s {kind}[{j}].{key} is {v}, outside 0…1"
                        ));
                    }
                }
                for (key, v) in [("w", b.w), ("h", b.h)] {
                    if v <= 0.0 {
                        return Err(format!(
                            "subjects sample {i}'s {kind}[{j}].{key} is {v}; a box's size must \
                             be greater than 0"
                        ));
                    }
                }
                if let Some(mouth) = b.mouth {
                    if kind != "faces" {
                        return Err(format!(
                            "subjects sample {i}'s {kind}[{j}] has a mouth; only a face box has \
                             one"
                        ));
                    }
                    if !(mouth.is_finite() && mouth >= 0.0) {
                        return Err(format!(
                            "subjects sample {i}'s faces[{j}].mouth is {mouth}; a mouth opening \
                             must be a number of at least 0"
                        ));
                    }
                }
            }
        }
    }
    check_cursor(&subjects.cursor)?;
    check_turns(&subjects.turns)
}

/// VR-60 (d)'s turn refusals: the count, each turn's span, and starts that
/// never go back (crosstalk turns share a span, so equal starts stand).
fn check_turns(turns: &[Turn]) -> Result<(), String> {
    let n = turns.len();
    if n > MAX_SUBJECT_SAMPLES {
        return Err(format!(
            "subjects holds {n} turns, more than {MAX_SUBJECT_SAMPLES}"
        ));
    }
    let mut previous: Option<Ticks> = None;
    for (i, turn) in turns.iter().enumerate() {
        if turn.from >= turn.to {
            return Err(format!(
                "subjects turns[{i}] runs from {} to {}; a turn must end after it starts",
                turn.from, turn.to
            ));
        }
        if let Some(p) = previous.filter(|&p| turn.from < p) {
            return Err(format!(
                "subjects turns[{i}] starts at {}, before the one before it ({p}); turns must \
                 be in time order",
                turn.from
            ));
        }
        previous = Some(turn.from);
    }
    Ok(())
}

/// VR-50's three refusals, each naming `cursor[i]`.
fn check_cursor(points: &[CursorPoint]) -> Result<(), String> {
    let n = points.len();
    if n > MAX_SUBJECT_SAMPLES {
        return Err(format!(
            "subjects holds {n} cursor points, more than {MAX_SUBJECT_SAMPLES}"
        ));
    }
    let mut previous: Option<Ticks> = None;
    for (i, point) in points.iter().enumerate() {
        if let Some(p) = previous.filter(|&p| point.t <= p) {
            return Err(format!(
                "subjects cursor[{i}] is at {}, not after the one before it ({p}); cursor \
                 times must be strictly increasing",
                point.t
            ));
        }
        previous = Some(point.t);
        for (key, v) in [("x", point.x), ("y", point.y)] {
            if !(0.0..=1.0).contains(&v) {
                return Err(format!("subjects cursor[{i}].{key} is {v}, outside 0…1"));
            }
        }
    }
    Ok(())
}

1	//! The framing path's keys (road map "creator-jobs" VR2a1 and VR2a2, spec
2	//! §11 VR-23, VR-24): what the chosen subject per sample becomes as keys of
3	//! F. VR-23's moves — the median-filtered subject point, the dead zone, the
4	//! speed, the spacing — moved here whole from `reframe.rs`, which keeps the
5	//! frames, the composition and the mapping into clip time; VR-24 adds what
6	//! a real recording needs beyond them:
7	//!
8	//! - **a hard cut at each shot change** — a one-frame `linear` segment
9	//!   ending exactly on the first canvas frame that shows the new shot, onto
10	//!   the new shot's subject's median over its first second;
11	//! - **loss** — a subject gone is held [`LOSS_HOLD`], then another subject is
12	//!   followed, or the framing eases over [`EMPTY_EASE`] to the `where_empty`
13	//!   state and the path goes EMPTY;
14	//! - **return** — from EMPTY once a subject has been seen for
15	//!   [`RETURN_SEEN`];
16	//! - **two people** framed together when both boxes, widened by
17	//!   [`PAIR_WIDEN`], fit the window.
18	//!
19	//! No move or ease ends after the frame before a cut, and a cut counts as a
20	//! move's end for VR-23's spacing. Every key is on the canvas's grid and the
21	//! keys are strictly increasing.
22	
23	use crate::actions::ease;
24	use crate::model::Curve;
25	use crate::reframe::{
26	    Frame, FramingKey, FramingPath, FramingRequest, FramingTuning, Point, WhereEmpty,
27	};
28	pub use crate::reframe_tracks::LOSS_HOLD;
29	use crate::reframe_tracks::{median, Chosen, SubjectBox, SubjectKind};
30	use crate::time::{
31	    one_frame, snap_down_to_frame, snap_to_frame, snap_up_to_frame, Fps, Ticks, TIMESCALE,
32	};
33	
34	/// The ease to `where_empty` after a loss: 0.8 s.
35	pub const EMPTY_EASE: Ticks = TIMESCALE * 4 / 5;
36	/// How long a subject must be seen at every sample before the framing
37	/// returns to it from EMPTY: 0.6 s.
38	pub const RETURN_SEEN: Ticks = TIMESCALE * 3 / 5;
39	/// A cut places the new shot on its subject's median over this: 1 s.
40	pub const CUT_MEDIAN: Ticks = TIMESCALE;
41	/// Each of two people's boxes is widened by this about its centre before
42	/// their union is tested against the window.
43	pub const PAIR_WIDEN: f64 = 1.15;
44	
45	/// The subject point's median reads ±0.5 s.
46	const MEDIAN_SPAN: Ticks = TIMESCALE / 2;
47	/// The shortest move: 0.4 s.
48	pub(crate) const MOVE_MIN: f64 = 0.4;
49	/// No move within 0.5 s of the last one's end…
50	pub(crate) const MOVE_SPACING: Ticks = TIMESCALE / 2;
51	
52	impl FramingPath {
53	    /// (scale, x, y) at clip tick `t`: the segment ending at key i eases with
54	    /// key i's curve (`actions::ease`); before the first key its value, after
55	    /// the last its value.
56	    pub fn at(&self, t: Ticks) -> (f64, f64, f64) {
57	        let value = |k: &FramingKey| (k.scale, k.x, k.y);
58	        let Some(first) = self.keys.first() else {
59	            return (1.0, 0.0, 0.0);
60	        };
61	        let Some(i) = self.keys.iter().position(|k| k.t >= t) else {
62	            return value(self.keys.last().expect("not empty"));
63	        };
64	        if i == 0 {
65	            return value(first);
66	        }
67	        let (a, b) = (&self.keys[i - 1], &self.keys[i]);
68	        let e = ease(b.curve, (t - a.t) as f64 / (b.t - a.t) as f64);
69	        (
70	            a.scale + (b.scale - a.scale) * e,
71	            a.x + (b.x - a.x) * e,
72	            a.y + (b.y - a.y) * e,
73	        )
74	    }
75	
76	    /// Keys whose (scale, x, y) differ from the previous key's.
77	    pub fn moves(&self) -> usize {
78	        self.keys
79	            .windows(2)
80	            .filter(|w| (w[0].scale, w[0].x, w[0].y) != (w[1].scale, w[1].x, w[1].y))
81	            .count()
82	    }
83	}
84	
85	/// What the framing holds: a window centred on a source-canvas point, or
86	/// the whole picture fitted.
87	#[derive(Debug, Clone, Copy, PartialEq)]
88	enum At {
89	    Window(Point),
90	    Fit,
91	}
92	
93	/// The keys as they are written, and the state they leave.
94	struct Writer<'a> {
95	    frame: &'a Frame,
96	    keys: Vec<FramingKey>,
97	    current: At,
98	    shows_fit: bool,
99	    last_end: Option<Ticks>,
100	}
101	
102	impl Writer<'_> {
103	    fn key(&self, t: Ticks, at: At, curve: Curve) -> FramingKey {
104	        match at {
105	            At::Window(wc) => self.frame.key(t, wc, curve),
106	            At::Fit => self.frame.fit_key(t, curve),
107	        }
108	    }
109	
110	    /// A hold key at `start` (unless the last key is there already) and the
111	    /// key `to` at `end` with `curve`.
112	    fn go(&mut self, start: Ticks, end: Ticks, to: At, curve: Curve) {
113	        if start > self.keys.last().expect("the first key").t {
114	            self.keys.push(self.key(start, self.current, Curve::Linear));
115	        }
116	        self.keys.push(self.key(end, to, curve));
117	        self.shows_fit |= to == At::Fit;
118	        self.current = to;
119	        self.last_end = Some(end);
120	    }
121	
122	    fn running(&self, t: Ticks) -> bool {
123	        self.last_end.is_some_and(|end| t < end)
124	    }
125	}
126	
127	/// The subject point and offset of a chosen sample (VR-22), its pair's
128	/// union standing in when both widened boxes fit the window (VR-24 (g)).
129	fn point_of(frame: &Frame, c: &Chosen, headroom: f64) -> Option<(SubjectKind, Point, Point)> {
130	    let (kind, b) = (c.kind?, c.subject?);
131	    let widened = |b: &SubjectBox| {
132	        let (cx, cy) = (b.x + b.w / 2.0, b.y + b.h / 2.0);
133	        let (w, h) = (b.w * PAIR_WIDEN, b.h * PAIR_WIDEN);
134	        (cx - w / 2.0, cy - h / 2.0, cx + w / 2.0, cy + h / 2.0)
135	    };
136	    let pair = c.second.and_then(|other| {
137	        let (a, o) = (widened(&b), widened(&other));
138	        let (x0, y0) = (a.0.min(o.0), a.1.min(o.1));
139	        let (x1, y1) = (a.2.max(o.2), a.3.max(o.3));
140	        let (p0, p1) = (frame.point(c.t, x0, y0), frame.point(c.t, x1, y1));
141	        let fits = p1.0 - p0.0 <= frame.window.0 && p1.1 - p0.1 <= frame.window.1;
142	        fits.then_some(SubjectBox {
143	            x: x0,
144	            y: y0,
145	            w: x1 - x0,
146	            h: y1 - y0,
147	            c: b.c,
148	            mouth: None,
149	        })
150	    });
151	    let (p, offset) = frame.subject(c.t, kind, &pair.unwrap_or(b), headroom);
152	    Some((kind, p, offset))
153	}
154	
155	/// The keys of one clip's path (spec §11 VR-23, VR-24): `chosen` one per
156	/// sample in clip ticks, `shots` the cuts in clip ticks (`Round::Up`).
157	pub(crate) fn write_keys(
158	    frame: &Frame,
159	    chosen: &[Chosen],
160	    shots: &[Ticks],
161	    duration: Ticks,
162	    fps: Fps,
163	    request: &FramingRequest,
164	    tuning: &FramingTuning,
165	) -> FramingPath {
166	    let shot = |t: Ticks| shots.partition_point(|&c| c <= t);
167	    let (ww, wh) = frame.window;
168	    let one = one_frame(fps);
169	    // Each kept cut: its shot's clip tick and its key time `c`, the first
170	    // canvas frame that shows the new shot (VR-24 (a)).
171	    let mut cuts: Vec<(Ticks, Ticks)> = shots
172	        .iter()
173	        .map(|&s| (s, snap_up_to_frame(s, fps)))
174	        .filter(|&(_, c)| c > one && c < duration)
175	        .collect();
176	    cuts.dedup_by_key(|&mut (_, c)| c);
177	    let empty_state = match request.where_empty {
178	        WhereEmpty::Center => At::Window(frame.centre()),
179	        WhereEmpty::Fit => At::Fit,
180	    };
181	
182	    // Each chosen sample's kind, subject point and offset (VR-22, VR-24 (g)).
183	    let points: Vec<Option<(SubjectKind, Point, Point)>> = chosen
184	        .iter()
185	        .map(|c| point_of(frame, c, tuning.headroom))
186	        .collect();
187	    // The median over ±0.5 s of the same kind in the same shot, then the
188	    // desired window centre, clamped (VR-23).
189	    let filtered: Vec<Option<(Point, Point)>> = (0..chosen.len())
190	        .map(|i| {
191	            let (kind, _, offset) = points[i]?;
192	            let t = chosen[i].t;
193	            let lo = chosen.partition_point(|q| q.t < t - MEDIAN_SPAN);
194	            let hi = chosen.partition_point(|q| q.t <= t + MEDIAN_SPAN);
195	            let near: Vec<Point> = (lo..hi)
196	                .filter_map(|j| points[j].filter(|q| q.0 == kind).map(|q| (j, q.1)))
197	                .filter(|&(j, _)| shot(chosen[j].t) == shot(t))
198	                .map(|(_, p)| p)
199	                .collect();
200	            let mut xs: Vec<f64> = near.iter().map(|p| p.0).collect();
201	            let mut ys: Vec<f64> = near.iter().map(|p| p.1).collect();
202	            let fp = (median(&mut xs), median(&mut ys));
203	            Some((fp, frame.clamp((fp.0 + offset.0, fp.1 + offset.1))))
204	        })
205	        .collect();
206	
207	    // The first key (VR-24 (f)): the first chosen sample's desired centre
208	    // when one is chosen within `LOSS_HOLD` in the first shot, else EMPTY.
209	    let first_cut = cuts.first().map_or(Ticks::MAX, |&(s, _)| s);
210	    let first = (0..chosen.len()).find(|&i| filtered[i].is_some());
211	    let (start_at, mut following) = match first {
212	        Some(i) if chosen[i].t < LOSS_HOLD && chosen[i].t < first_cut => (
213	            At::Window(filtered[i].expect("chosen").1),
214	            chosen[i].identity,
215	        ),
216	        _ => (empty_state, None),
217	    };
218	    let mut empty = start_at == empty_state && following.is_none();
219	    let mut w = Writer {
220	        frame,
221	        keys: Vec::new(),
222	        current: start_at,
223	        shows_fit: start_at == At::Fit,
224	        last_end: None,
225	    };
226	    w.keys.push(w.key(0, start_at, Curve::Linear));
227	    let mut cut_keys: Vec<Ticks> = Vec::new();
228	
229	    let mut loss: Option<Ticks> = None;
230	    let mut seen: Option<Ticks> = None;
231	    let mut next = 0usize;
232	    // The frame before a cut's, and the latest a move or an ease may end:
233	    // the frame before the next cut.
234	    let before = |c: Ticks| snap_down_to_frame(c - 1, fps);
235	    let limit = |next: usize| cuts.get(next).map_or(duration, |&(_, c)| before(c));
236	    let mut i = 0usize;
237	    while i <= chosen.len() {
238	        let t = chosen.get(i).map_or(Ticks::MAX, |c| c.t);
239	        // Each cut at or before this sample, in order (VR-24 (b)).
240	        while next < cuts.len() && cuts[next].0 <= t {
241	            let (s, c) = cuts[next];
242	            let in_shot: Vec<usize> = (0..chosen.len())
243	                .filter(|&j| shot(chosen[j].t) == shot(s) && chosen[j].t < c + CUT_MEDIAN)
244	                .collect();
245	            let lead = in_shot.iter().copied().find(|&j| points[j].is_some());
246	            let to = match lead {
247	                Some(l) => {
248	                    let (kind, _, offset) = points[l].expect("chosen");
249	                    let same: Vec<Point> = in_shot
250	                        .iter()
251	                        .filter(|&&j| chosen[j].identity == chosen[l].identity)
252	                        .filter_map(|&j| points[j].filter(|q| q.0 == kind).map(|q| q.1))
253	                        .collect();
254	                    let mut xs: Vec<f64> = same.iter().map(|p| p.0).collect();
255	                    let mut ys: Vec<f64> = same.iter().map(|p| p.1).collect();
256	                    let m = (median(&mut xs), median(&mut ys));
257	                    At::Window(frame.clamp((m.0 + offset.0, m.1 + offset.1)))
258	                }
259	                None => empty_state,
260	            };
261	            if to != w.current {
262	                w.go(before(c), c, to, Curve::Linear);
263	                cut_keys.push(c);
264	            }
265	            w.last_end = Some(c);
266	            empty = lead.is_none();
267	            following = lead.and_then(|l| chosen[l].identity);
268	            loss = None;
269	            seen = None;
270	            next += 1;
271	        }
272	        let Some(c) = chosen.get(i) else { break };
273	        i += 1;
274	        let has = filtered[i - 1];
275	        if empty {
276	            // Return from EMPTY (VR-24 (e)).
277	            if has.is_none() {
278	                seen = None;
279	                continue;
280	            }
281	            let since = *seen.get_or_insert(t);
282	            if t - since < RETURN_SEEN || w.running(t) {
283	                continue;
284	            }
285	            let desired = has.expect("chosen").1;
286	            let centre = frame.centre();
287	            let distance = (desired.0 - centre.0).hypot(desired.1 - centre.1);
288	            let seconds = MOVE_MIN.max(distance / (tuning.speed * ww));
289	            if let Some((start, end)) = span(t, seconds, duration, fps) {
290	                if end <= limit(next) {
291	                    w.go(start, end, At::Window(desired), Curve::EaseInOut);
292	                    empty = false;
293	                    following = c.identity;
294	                    seen = None;
295	                    loss = None;
296	                }
297	            }
298	            continue;
299	        }
300	        // Loss (VR-24 (d)).
301	        match loss {
302	            None if has.is_none() || (c.lost && c.identity != following) => {
303	                loss = Some(t);
304	                continue;
305	            }
306	            None => {}
307	            Some(t0) => {
308	                if has.is_some() && !c.lost && c.identity == following {
309	                    loss = None;
310	                } else if t - t0 < LOSS_HOLD {
311	                    continue;
312	                } else if has.is_some() {
313	                    loss = None;
314	                } else {
315	                    if !w.running(t) {
316	                        let seconds = EMPTY_EASE as f64 / TIMESCALE as f64;
317	                        if let Some((start, end)) = span(t, seconds, duration, fps) {
318	                            if end <= limit(next) {
319	                                w.go(start, end, empty_state, Curve::EaseInOut);
320	                                empty = true;
321	                                loss = None;
322	                                seen = None;
323	                                following = None;
324	                            }
325	                        }
326	                    }
327	                    continue;
328	                }
329	            }
330	        }
331	        following = c.identity;
332	        // VR-23's move.
333	        let (fp, desired) = has.expect("chosen");
334	        let At::Window(current) = w.current else {
335	            continue;
336	        };
337	        if w.running(t) {
338	            continue;
339	        }
340	        let (dx, dy) = (desired.0 - current.0, desired.1 - current.1);
341	        if dx.abs() <= tuning.dead_zone_width * ww && dy.abs() <= tuning.dead_zone_height * wh {
342	            continue;
343	        }
344	        let outside = (fp.0 - current.0).abs() > ww / 2.0 || (fp.1 - current.1).abs() > wh / 2.0;
345	        if w.last_end.is_some_and(|end| t < end + MOVE_SPACING) && !outside {
346	            continue;
347	        }
348	        let seconds = MOVE_MIN.max(dx.hypot(dy) / (tuning.speed * ww));
349	        if let Some((start, end)) = span(t, seconds, duration, fps) {
350	            if end <= limit(next) {
351	                w.go(start, end, At::Window(desired), Curve::EaseInOut);
352	            }
353	        }
354	    }
355	    FramingPath {
356	        keys: w.keys,
357	        shows_fit: w.shows_fit,
358	        cuts: cut_keys,
359	    }
360	}
361	
362	/// A move of `seconds` from sample `t`, snapped (VR-23): at least a frame,
363	/// and `None` when it would end past the clip.
364	pub(crate) fn span(t: Ticks, seconds: f64, duration: Ticks, fps: Fps) -> Option<(Ticks, Ticks)> {
365	    let length = (seconds * TIMESCALE as f64).min((duration as f64) * 2.0 + 1.0);
366	    let start = snap_to_frame(t, fps);
367	    let mut end = snap_to_frame(t.saturating_add(length.round() as Ticks), fps);
368	    if end <= start {
369	        end = snap_up_to_frame(start + 1, fps);
370	    }
371	    (end <= duration).then_some((start, end))
372	}
373	//! `reframe_clip` — one clip framed on the current canvas (road map
374	//! "creator-jobs" VR2a2 and VR2b1, spec §11 VR-26, VR-27). The planner is
375	//! `reframe.rs`'s (VR-20…VR-24), the writing `reframe_compose.rs`'s (the
376	//! path composed into the base and the actions the clip already carries,
377	//! VR-27) and `reframe_cover.rs`'s (`keep`, the backdrop, VR-25); this
378	//! module reads the arguments, refuses in VR-26's order, and finishes.
379	//! `replace: true` strips `x`, `y` and `scale` from the ends and fits the
380	//! base before planning, for every follow but `keep`.
381	//!
382	//! **What reads what.** The FOLLOWING kinds (`subject`, `face`, `person`,
383	//! `salient`) plan over `subjects`; `center` and `fit` are `fixed_framing`;
384	//! `keep` is `set_canvas`'s rescale on the base. `layout` (VR5b, spec §11
385	//! VR-53) re-lays a camera's switches and its screen's on the current
386	//! canvas through `reframe_layout.rs`, reading no `zoom`, `where_empty`,
387	//! `backdrop`, `replace` or `subjects` and skipping refusals (5) and (6) as
388	//! `keep` does. Only `keep` and `layout` read `from_*`
389	//! (every other placement is measured from a canvas centre, so the source
390	//! size cancels), `fit` and `keep` ignore `zoom`, and only the following
391	//! kinds read `where_empty` and `subjects`; a value that cannot be read is
392	//! an `Err` whatever the follow. `cursor` (VR5, spec §11 VR-50) plans over
393	//! `subjects.cursor` with `reframe_cursor.rs`'s planner and reads no
394	//! `where_empty`; a face follow never reads the cursor, and a clip whose
395	//! media has a cursor file is never followed by faces (VR-51).
396	//!
397	//! `speaker` (VR6a, spec §11 VR-60, VR-61) frames a wide shot on whoever
398	//! speaks: it reads `subjects` (its faces' `mouth` and its `turns`) and
399	//! `mics`, `mic_faces`, `zoom`, `where_empty`, `backdrop` and `replace` as
400	//! `face` does, and plans through `reframe_speaker.rs`; its subject-free
401	//! refusals (the microphones', `mic_faces`') come here after (5)–(6) and
402	//! before `subjects`' values, and the rest are the planner's sentences after
403	//! "no subjects". No other follow reads `mics` or `mic_faces`.
404	//!
405	//! **Why "no subjects" is refused LAST.** The tool fills `subjects` from the
406	//! analysis cache (VR-28) and first tries the op without them: every other
407	//! refusal must answer that trial, so only a clip that could be framed waits
408	//! for an analysis. [`no_subjects`] is the sentence both sides know.
409	//!
410	//! **`subjects` is read strictly** (`reframe_subjects.rs`, its reader and
411	//! [`check_subjects`]).
