507	    /// The op (spec §11 VR-26; this module's doc, and `edit.rs`'s row).
508	    pub fn reframe_clip(&self, r: &Reframe) -> Result<Outcome, String> {
509	        let clip = self.require_clip(r.clip)?.clone();
510	        if let Some(z) = r
511	            .zoom
512	            .filter(|z| !(z.is_finite() && (1.0..=4.0).contains(z)))
513	        {
514	            return Err(format!("zoom must be between 1 and 4 times fill, not {z}"));
515	        }
516	        for (key, value) in [("from_width", r.from_width), ("from_height", r.from_height)] {
517	            if value == Some(0) {
518	                return Err(format!("{key} must be greater than 0, not 0"));
519	            }
520	        }
521	        if let Some(track) = r.backdrop {
522	            self.require_track(track)?;
523	        }
524	        if r.follow == FramingFollow::Speaker {
525	            for &mic in r.mics.iter().flatten() {
526	                self.require_clip(mic)?;
527	            }
528	        }
529	        match self.refusal(&clip, r) {
530	            Some(why) => Ok(Outcome::Refused(why)),
531	            None => self.reframed(&clip, r),
532	        }
533	    }
534	
535	    /// Refusals (1)–(6) and (8) of VR-26, in order ((7) removed by VR-27),
536	    /// VR-50's and VR-51's after the nest and still refusals.
537	    fn refusal(&self, clip: &Clip, r: &Reframe) -> Option<String> {
538	        let id = clip.id;
539	        let keep = r.follow == FramingFollow::Keep;
540	        let following = r.follow.reads_subjects();
541	        let kind = match clip.source {
542	            Source::Text => "text",
543	            Source::Shape => "shape",
544	            Source::Graphic => "graphic",
545	            Source::Adjustment => "adjustment",
546	            _ => "",
547	        };
548	        if !kind.is_empty() {
549	            return (!keep).then(|| {
550	                format!(
551	                    "clip {id} is a {kind} clip, with no picture to frame; only keep reframes it"
552	                )
553	            });
554	        }
555	        let picture = match clip.source {
556	            Source::Media { media, .. } | Source::Still { media, .. } => self
557	                .media(media)
558	                .is_some_and(|m| m.has_video && m.kind == MediaKind::Video),
559	            _ => true,
560	        };
561	        let Some((mw, mh)) = self.source_size(clip).filter(|_| picture) else {
562	            return Some(format!("clip {id}'s media has no picture to frame"));
563	        };
564	        let video = clip.video.clone().unwrap_or_default();
565	        let crop = video.crop;
566	        if !(mw - crop.l - crop.r > 0.0
567	            && mh - crop.t - crop.b > 0.0
568	            && video.scale.is_finite()
569	            && video.scale > 0.0)
570	        {
571	            return Some(no_picture(id));
572	        }
573	        if following {
574	            match clip.source {
575	                Source::Nest { .. } => {
576	                    return Some(format!(
577	                        "clip {id} shows a nest, which has no subjects to follow; frame it with \
578	                         center, fit or keep"
579	                    ))
580	                }
581	                Source::Still { .. } | Source::Image { .. } => {
582	                    return Some(format!(
583	                        "clip {id} shows a still picture, which has no subjects to follow; frame \
584	                         it with center, fit or keep"
585	                    ))
586	                }
587	                Source::Media { media, .. } => {
588	                    let cursor = self.media(media).is_some_and(|m| m.cursor.is_some());
589	                    if r.follow == FramingFollow::Cursor && !cursor {
590	                        return Some(no_cursor_file(id));
591	                    }
592	                    if r.follow != FramingFollow::Cursor && cursor {
593	                        return Some(cursor_not_faces(id));
594	                    }
595	                }
596	                _ => {}
597	            }
598	        }
599	        // `layout` re-lays switches that passed CO-62 when made (VR-53 (c)).
600	        if !keep && r.follow != FramingFollow::Layout {
601	            if let Some(why) = self.matte_refusal(clip) {
602	                return Some(why);
603	            }
604	            if let Some(why) = turn_refusal(id, clip, &video) {
605	                return Some(why);
606	            }
607	        }
608	        if r.follow == FramingFollow::Speaker {
609	            let (mics, faces) = (r.mics.as_deref(), r.mic_faces.as_deref());
610	            if let Some(why) = mics_refusal(self, id, mics, faces) {
611	                return Some(why);
612	            }
613	        }
614	        if following {
615	            if let Some(Err(why)) = r.subjects.as_ref().map(check_subjects) {
616	                return Some(why);
617	            }
618	        }
619	        None
620	    }
