362	/// A move of `seconds` from sample `t`, snapped (VR-23): at least a frame,
363	/// and `None` when it would end past the clip.
364	pub(crate) fn span(t: Ticks, seconds: f64, duration: Ticks, fps: Fps) -> Option<(Ticks, Ticks)> {
365	    let length = (seconds * TIMESCALE as f64).min((duration as f64) * 2.0 + 1.0);
366	    let start = snap_to_frame(t, fps);
367	    let mut end = snap_to_frame(t.saturating_add(length.round() as Ticks), fps);
368	    if end <= start {
369	        end = snap_up_to_frame(start + 1, fps);
370	    }
371	    (end <= duration).then_some((start, end))
372	}
373	//! `reframe_clip` — one clip framed on the current canvas (road map
374	//! "creator-jobs" VR2a2 and VR2b1, spec §11 VR-26, VR-27). The planner is
375	//! `reframe.rs`'s (VR-20…VR-24), the writing `reframe_compose.rs`'s (the
376	//! path composed into the base and the actions the clip already carries,
377	//! VR-27) and `reframe_cover.rs`'s (`keep`, the backdrop, VR-25); this
378	//! module reads the arguments, refuses in VR-26's order, and finishes.
379	//! `replace: true` strips `x`, `y` and `scale` from the ends and fits the
380	//! base before planning, for every follow but `keep`.
381	//!
382	//! **What reads what.** The FOLLOWING kinds (`subject`, `face`, `person`,
383	//! `salient`) plan over `subjects`; `center` and `fit` are `fixed_framing`;
384	//! `keep` is `set_canvas`'s rescale on the base. `layout` (VR5b, spec §11
385	//! VR-53) re-lays a camera's switches and its screen's on the current
386	//! canvas through `reframe_layout.rs`, reading no `zoom`, `where_empty`,
387	//! `backdrop`, `replace` or `subjects` and skipping refusals (5) and (6) as
388	//! `keep` does. Only `keep` and `layout` read `from_*`
389	//! (every other placement is measured from a canvas centre, so the source
390	//! size cancels), `fit` and `keep` ignore `zoom`, and only the following
391	//! kinds read `where_empty` and `subjects`; a value that cannot be read is
392	//! an `Err` whatever the follow. `cursor` (VR5, spec §11 VR-50) plans over
393	//! `subjects.cursor` with `reframe_cursor.rs`'s planner and reads no
394	//! `where_empty`; a face follow never reads the cursor, and a clip whose
395	//! media has a cursor file is never followed by faces (VR-51).
396	//!
397	//! `speaker` (VR6a, spec §11 VR-60, VR-61) frames a wide shot on whoever
398	//! speaks: it reads `subjects` (its faces' `mouth` and its `turns`) and
399	//! `mics`, `mic_faces`, `zoom`, `where_empty`, `backdrop` and `replace` as
400	//! `face` does, and plans through `reframe_speaker.rs`; its subject-free
401	//! refusals (the microphones', `mic_faces`') come here after (5)–(6) and
402	//! before `subjects`' values, and the rest are the planner's sentences after
403	//! "no subjects". No other follow reads `mics` or `mic_faces`.
404	//!
405	//! **Why "no subjects" is refused LAST.** The tool fills `subjects` from the
406	//! analysis cache (VR-28) and first tries the op without them: every other
407	//! refusal must answer that trial, so only a clip that could be framed waits
408	//! for an analysis. [`no_subjects`] is the sentence both sides know.
409	//!
410	//! **`subjects` is read strictly** (`reframe_subjects.rs`, its reader and
411	//! [`check_subjects`]).
412	
