641	    /// Planned, refused (9) and (10), written and finished.
642	    fn reframed(&self, clip: &Clip, r: &Reframe) -> Result<Outcome, String> {
643	        let id = clip.id;
644	        let zoom = r.zoom.unwrap_or(1.0);
645	        let canvas = (self.canvas.width, self.canvas.height);
646	        let from = (r.from_width, r.from_height);
647	        let from = (from.0.unwrap_or(canvas.0), from.1.unwrap_or(canvas.1));
648	        match r.follow {
649	            FramingFollow::Keep => return self.finish(self.kept(id, from)),
650	            FramingFollow::Layout => return self.relaid(id, from),
651	            _ => {}
652	        }
653	        // VR-27 (g): the strip and the Fit base come before the plan.
654	        let stripped;
655	        let source = if r.replace == Some(true) {
656	            stripped = self.replaced(id);
657	            &stripped
658	        } else {
659	            self
660	        };
661	        let path = match (r.follow, r.follow.following()) {
662	            (FramingFollow::Center, _) => fixed_framing(source, id, WhereEmpty::Center, zoom),
663	            (FramingFollow::Fit, _) => fixed_framing(source, id, WhereEmpty::Fit, 1.0),
664	            (FramingFollow::Speaker, _) => {
665	                let Some(subjects) = &r.subjects else {
666	                    return Ok(Outcome::Refused(no_subjects(id)));
667	                };
668	                let mics = r.mics.as_deref().unwrap_or(&[]);
669	                let empty = r.where_empty.unwrap_or_default();
670	                let faces = r.mic_faces.as_deref();
671	                match plan_speaker_framing(source, id, subjects, mics, faces, zoom, empty) {
672	                    Ok(path) => Some(path),
673	                    Err(why) => return Ok(Outcome::Refused(why)),
674	                }
675	            }
676	            (FramingFollow::Cursor, _) => {
677	                let Some(subjects) = &r.subjects else {
678	                    return Ok(Outcome::Refused(no_subjects(id)));
679	                };
680	                plan_cursor_framing(source, id, &subjects.cursor, zoom)
681	            }
682	            (_, Some(follow)) => {
683	                let Some(subjects) = &r.subjects else {
684	                    return Ok(Outcome::Refused(no_subjects(id)));
685	                };
686	                let request = FramingRequest {
687	                    follow,
688	                    zoom,
689	                    from_width: canvas.0,
690	                    from_height: canvas.1,
691	                    where_empty: r.where_empty.unwrap_or_default(),
692	                };
693	                plan_framing(source, id, subjects, &request, &FRAMING_TUNING)
694	            }
695	            (_, None) => None,
696	        };
697	        // No path is unreached: every arm the planner has is refused above.
698	        let Some(path) = path else {
699	            return Ok(Outcome::Refused(no_picture(id)));
700	        };
701	        let backdrop = r.backdrop.filter(|_| path.shows_fit);
702	        let original = Clip {
703	            video: Some(clip.video.clone().unwrap_or_default()),
704	            ..clip.clone()
705	        };
706	        if let Some(track) = backdrop {
707	            if let Err(why) = self.blurred_copy(&original, 0, 0) {
708	                return Ok(Outcome::Refused(why));
709	            }
710	            if self.track_index(track) >= self.track_index(clip.track) {
711	                return Ok(Outcome::Refused(format!(
712	                    "track {track} is not behind clip {id}'s track, so a backdrop there would \
713	                     cover it"
714	                )));
715	            }
716	        }
717	        if let (Some(_), Some(subjects)) = (r.follow.following(), &r.subjects) {
718	            if in_clip_time(clip, self, subjects).0.is_empty() {
719	                return Ok(Outcome::Refused(no_subjects(id)));
720	            }
721	        }
722	        if let (FramingFollow::Cursor, Some(subjects)) = (r.follow, &r.subjects) {
723	            if cursor_in_clip_time(clip, self, &subjects.cursor).is_empty() {
724	                return Ok(Outcome::Refused(no_subjects(id)));
725	            }
726	        }
727	        let (mut next, _) = source.composed(id, &path);
728	        if let Some(track) = backdrop {
729	            next = next.with_backdrop(&original, track)?;
730	        }
731	        self.finish(next)
732	    }
733	}
