740	/// Refusal (6): a turned base, an action end turning the clip, or a spin.
741	fn turn_refusal(id: u32, clip: &Clip, video: &VideoProps) -> Option<String> {
742	    let upright = "framing works on an upright picture; only keep reframes it";
743	    if video.rotation != 0.0 {
744	        return Some(format!(
745	            "clip {id} is turned {}°, and {upright}",
746	            video.rotation
747	        ));
748	    }
749	    let turning = |a: &&Action| {
750	        a.end["video"]["rotation"]
751	            .as_f64()
752	            .is_some_and(|r| r != 0.0)
753	    };
754	    if let Some(action) = clip.actions.iter().find(turning) {
755	        return Some(format!(
756	            "clip {id}'s action {} turns it, and {upright}",
757	            action.id
758	        ));
759	    }
760	    let spins = video.motion.as_ref().is_some_and(|m| {
761	        [m.r#in, m.out]
762	            .iter()
763	            .flatten()
764	            .any(|e| e.kind == EdgeMotion::Spin)
765	            || m.during.is_some_and(|d| d.kind == DuringMotion::Spin)
766	    });
767	    spins.then(|| format!("clip {id} spins in its motion, and {upright}"))
768	}
