1	//! Choosing the subject to follow (road map "creator-jobs" VR2a1, spec §11
2	//! VR-21): boxes found per sample, linked into tracks here, and one track
3	//! chosen per sample. Nothing is stored (CJ-31): the planner builds the
4	//! tracks over the samples it is handed, every time.
5	//!
6	//! The analyses find boxes per sample and never track (VR-4), so a "who" is
7	//! this module's: a box joins the track of its kind whose last box is at
8	//! most [`LINK_GAP`] earlier and overlaps it most (IoU at least
9	//! [`LINK_IOU`]), and a shot change ends every track, since a box after a
10	//! cut is a different picture whatever it overlaps. The choice then reads
11	//! each present track's score — how steadily it is there, how big, how
12	//! central — under three rules: a tier (faces over people over salient
13	//! regions, for `subject`), a face's own body standing in for it while it is
14	//! away, and hysteresis, so two near-equal faces do not trade the frame
15	//! back and forth. An absent primary is held [`LOSS_HOLD`] (VR2a2, spec §11
16	//! VR-24 (c)): the best present track stands in, marked `lost`, and replaces
17	//! the primary only once the hold has passed. All times are CLIP ticks,
18	//! samples strictly increasing.
19	
20	pub use crate::reframe_subjects::{SubjectBox, SubjectSample};
21	use crate::time::{Ticks, TIMESCALE};
22	
23	/// The least IoU at which a box continues a track.
24	pub const LINK_IOU: f64 = 0.3;
25	/// The longest gap a track bridges: 1 s.
26	pub const LINK_GAP: Ticks = TIMESCALE;
27	/// The share of shared samples in which a person box must hold a face's
28	/// centre for the person to be that face's body.
29	pub const BODY_SHARE: f64 = 0.8;
30	/// How much better a rival must score to replace the primary…
31	pub const RIVAL_MARGIN: f64 = 1.25;
32	/// …at every sample for this long: 2 s.
33	pub const RIVAL_HOLD: Ticks = 2 * TIMESCALE;
34	/// A score reads the samples within this of its own, in its shot: ±1 s.
35	const SCORE_SPAN: Ticks = TIMESCALE;
36	/// How long an absent primary is held before another track replaces it,
37	/// and how long a framing holds a lost subject (spec §11 VR-24): 1 s.
38	pub const LOSS_HOLD: Ticks = TIMESCALE;
39	
40	/// What a framing follows: `Subject` reads every kind in its tiers, the
41	/// others only their own kind.
42	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
43	pub enum Follow {
44	    Subject,
45	    Face,
46	    Person,
47	    Salient,
48	}
49	
50	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
51	pub enum SubjectKind {
52	    Face,
53	    Person,
54	    Salient,
55	}
56	
57	/// The choice at one sample: the kind, the track and its box there, or all
58	/// `None` when nothing is followed.
59	#[derive(Debug, Clone, Copy, PartialEq)]
60	pub struct Chosen {
61	    pub t: Ticks,
62	    pub kind: Option<SubjectKind>,
63	    pub track: Option<u32>,
64	    pub subject: Option<SubjectBox>,
65	    /// The chosen track's identity: a body's is its face's id (VR-21).
66	    pub identity: Option<u32>,
67	    /// Not its shot's first sample, and the primary identity — kept through
68	    /// a loss (VR-24 (c)) — has no present track here: what is chosen, if
69	    /// anything, is a stand-in.
70	    pub lost: bool,
71	    /// For a face or person pick: the best-scoring other present track of
72	    /// its tier with another identity, its box here (VR-24 (g)).
73	    pub second: Option<SubjectBox>,
74	}
75	
76	const KINDS: [SubjectKind; 3] = [SubjectKind::Face, SubjectKind::Person, SubjectKind::Salient];
77	
78	pub(crate) struct Track {
79	    pub(crate) id: u32,
80	    pub(crate) kind: SubjectKind,
81	    /// (sample index, box), ascending.
82	    pub(crate) boxes: Vec<(usize, SubjectBox)>,
83	}
84	
85	impl Track {
86	    pub(crate) fn at(&self, i: usize) -> Option<SubjectBox> {
87	        self.boxes
88	            .binary_search_by_key(&i, |b| b.0)
89	            .ok()
90	            .map(|n| self.boxes[n].1)
91	    }
92	}
93	
94	fn boxes_of(sample: &SubjectSample, kind: SubjectKind) -> &[SubjectBox] {
95	    match kind {
96	        SubjectKind::Face => &sample.faces,
97	        SubjectKind::Person => &sample.people,
98	        SubjectKind::Salient => &sample.salient,
99	    }
100	}
101	
102	pub(crate) fn iou(a: &SubjectBox, b: &SubjectBox) -> f64 {
103	    let w = (a.x + a.w).min(b.x + b.w) - a.x.max(b.x);
104	    let h = (a.y + a.h).min(b.y + b.h) - a.y.max(b.y);
105	    if w <= 0.0 || h <= 0.0 {
106	        return 0.0;
107	    }
108	    let inter = w * h;
109	    let union = a.w * a.h + b.w * b.h - inter;
110	    if union > 0.0 {
111	        inter / union
112	    } else {
113	        0.0
114	    }
115	}
116	
117	pub(crate) fn centre(b: &SubjectBox) -> (f64, f64) {
118	    (b.x + b.w / 2.0, b.y + b.h / 2.0)
119	}
120	
121	fn holds(outer: &SubjectBox, point: (f64, f64)) -> bool {
122	    (outer.x..=outer.x + outer.w).contains(&point.0)
123	        && (outer.y..=outer.y + outer.h).contains(&point.1)
124	}
125	
126	/// The median of `values` (the mean of the middle two when even); 0 when
127	/// empty. Sorts in place.
128	pub(crate) fn median(values: &mut [f64]) -> f64 {
129	    values.sort_by(f64::total_cmp);
130	    let n = values.len();
131	    match n {
132	        0 => 0.0,
133	        _ if n % 2 == 1 => values[n / 2],
134	        _ => (values[n / 2 - 1] + values[n / 2]) / 2.0,
135	    }
136	}
137	
138	/// Each sample's shot: the number of cuts at or before it.
139	pub(crate) fn shots_of(samples: &[SubjectSample], cuts: &[Ticks]) -> Vec<usize> {
140	    let mut cuts = cuts.to_vec();
141	    cuts.sort_unstable();
142	    samples
143	        .iter()
144	        .map(|s| cuts.partition_point(|&c| c <= s.t))
145	        .collect()
146	}
147	
148	/// Every kind's tracks, ids in creation order (samples in time order, and
149	/// within one faces, then people, then salient regions), and each sample's
150	/// present tracks. Only a track still open — its last box in the same shot
151	/// and at most [`LINK_GAP`] earlier — is a candidate.
152	pub(crate) fn link(
153	    samples: &[SubjectSample],
154	    shot: &[usize],
155	    kinds: &[SubjectKind],
156	) -> (Vec<Track>, Vec<Vec<usize>>) {
157	    let mut tracks: Vec<Track> = Vec::new();
158	    let mut present: Vec<Vec<usize>> = vec![Vec::new(); samples.len()];
159	    let mut open: Vec<usize> = Vec::new();
160	    for (i, sample) in samples.iter().enumerate() {
161	        open.retain(|&n| {
162	            let last = tracks[n].boxes.last().expect("a track has a box").0;
163	            shot[last] == shot[i] && sample.t - samples[last].t <= LINK_GAP
164	        });
165	        let before = open.clone();
166	        for &kind in kinds {
167	            for b in boxes_of(sample, kind) {
168	                let mut best: Option<(usize, f64)> = None;
169	                for &n in &before {
170	                    let (last, last_box) = *tracks[n].boxes.last().expect("a track has a box");
171	                    if tracks[n].kind != kind || last == i {
172	                        continue;
173	                    }
174	                    let overlap = iou(&last_box, b);
175	                    if overlap >= LINK_IOU && best.is_none_or(|(_, o)| overlap > o) {
176	                        best = Some((n, overlap));
177	                    }
178	                }
179	                let n = match best {
180	                    Some((n, _)) => {
181	                        tracks[n].boxes.push((i, *b));
182	                        n
183	                    }
184	                    None => {
185	                        let id = tracks.len() as u32;
186	                        tracks.push(Track {
187	                            id,
188	                            kind,
189	                            boxes: vec![(i, *b)],
190	                        });
191	                        open.push(tracks.len() - 1);
192	                        tracks.len() - 1
193	                    }
194	                };
195	                present[i].push(n);
196	            }
197	        }
198	        // Ascending ids, so a tie goes to the lower one.
199	        present[i].sort_unstable();
200	    }
201	    (tracks, present)
202	}
203	
204	/// For each person track, the face track it is the body of, if any: the one
205	/// with the most shared samples among those whose centre it holds in at
206	/// least [`BODY_SHARE`] of them.
207	fn bodies(tracks: &[Track]) -> Vec<Option<u32>> {
208	    tracks
209	        .iter()
210	        .map(|person| {
211	            if person.kind != SubjectKind::Person {
212	                return None;
213	            }
214	            let mut best: Option<(u32, usize)> = None;
215	            for face in tracks.iter().filter(|t| t.kind == SubjectKind::Face) {
216	                let (mut shared, mut held) = (0usize, 0usize);
217	                for &(i, pb) in &person.boxes {
218	                    if let Some(fb) = face.at(i) {
219	                        shared += 1;
220	                        held += usize::from(holds(&pb, centre(&fb)));
221	                    }
222	                }
223	                if shared > 0
224	                    && held as f64 >= BODY_SHARE * shared as f64
225	                    && best.is_none_or(|(_, n)| shared > n)
226	                {
227	                    best = Some((face.id, shared));
228	                }
229	            }
230	            best.map(|(id, _)| id)
231	        })
232	        .collect()
233	}
234	
235	/// A track's score at sample `i`: presence × median area × centrality over
236	/// the samples within [`SCORE_SPAN`] of it in its shot.
237	fn score(track: &Track, i: usize, samples: &[SubjectSample], shot: &[usize]) -> f64 {
238	    let t = samples[i].t;
239	    let in_window = |j: usize| shot[j] == shot[i] && (samples[j].t - t).abs() <= SCORE_SPAN;
240	    let lo = (0..=i)
241	        .rev()
242	        .take_while(|&j| in_window(j))
243	        .last()
244	        .unwrap_or(i);
245	    let hi = (i..samples.len())
246	        .take_while(|&j| in_window(j))
247	        .last()
248	        .unwrap_or(i);
249	    let from = track.boxes.partition_point(|b| b.0 < lo);
250	    let to = track.boxes.partition_point(|b| b.0 <= hi);
251	    let mut areas: Vec<f64> = track.boxes[from..to]
252	        .iter()
253	        .map(|(_, b)| b.w * b.h)
254	        .collect();
255	    let presence = areas.len() as f64 / (hi - lo + 1) as f64;
256	    let area = median(&mut areas);
257	    let (cx, cy) = track.at(i).map(|b| centre(&b)).unwrap_or((0.5, 0.5));
258	    let off = ((cx - 0.5).powi(2) + (cy - 0.5).powi(2)).sqrt();
259	    let centrality = 1.0 - (off / (0.5 * 2f64.sqrt())).min(1.0);
260	    presence * area * centrality
261	}
262	
263	/// One [`Chosen`] per sample (spec §11 VR-21). `samples` in clip ticks,
264	/// strictly increasing; `cuts` in clip ticks.
265	pub fn choose_subject(samples: &[SubjectSample], cuts: &[Ticks], follow: Follow) -> Vec<Chosen> {
266	    let kinds: &[SubjectKind] = match follow {
267	        Follow::Subject => &KINDS,
268	        Follow::Face => &KINDS[0..1],
269	        Follow::Person => &KINDS[1..2],
270	        Follow::Salient => &KINDS[2..3],
271	    };
272	    let shot = shots_of(samples, cuts);
273	    let (tracks, present) = link(samples, &shot, kinds);
274	    let body = if follow == Follow::Subject {
275	        bodies(&tracks)
276	    } else {
277	        vec![None; tracks.len()]
278	    };
279	    // A track's identity: a body is its face.
280	    let identity = |n: usize| body[n].unwrap_or(tracks[n].id);
281	    let mut primary: Option<u32> = None;
282	    let mut rivals: Vec<(u32, Ticks)> = Vec::new();
283	    // The first sample at which the primary had no present track (VR-24 (c)).
284	    let mut absent_since: Option<Ticks> = None;
285	    let mut out = Vec::with_capacity(samples.len());
286	    for (i, sample) in samples.iter().enumerate() {
287	        let first_of_shot = i == 0 || shot[i] != shot[i - 1];
288	        let tier = kinds
289	            .iter()
290	            .copied()
291	            .find(|&kind| present[i].iter().any(|&n| tracks[n].kind == kind));
292	        let Some(tier) = tier else {
293	            // Nothing present: a shot's first sample clears the primary, any
294	            // other sample counts towards its absence.
295	            if first_of_shot {
296	                primary = None;
297	                rivals.clear();
298	                absent_since = None;
299	            } else if primary.is_some() {
300	                absent_since.get_or_insert(sample.t);
301	            }
302	            out.push(Chosen {
303	                t: sample.t,
304	                kind: None,
305	                track: None,
306	                subject: None,
307	                identity: None,
308	                lost: primary.is_some() && !first_of_shot,
309	                second: None,
310	            });
311	            continue;
312	        };
313	        let candidates: Vec<(usize, f64)> = present[i]
314	            .iter()
315	            .copied()
316	            .filter(|&n| tracks[n].kind == tier)
317	            .map(|n| (n, score(&tracks[n], i, samples, &shot)))
318	            .collect();
319	        let best_of = |set: &mut dyn Iterator<Item = (usize, f64)>| {
320	            set.fold(None, |best: Option<(usize, f64)>, (n, s)| match best {
321	                Some((_, b)) if s <= b => best,
322	                _ => Some((n, s)),
323	            })
324	        };
325	        let best = best_of(&mut candidates.iter().copied()).expect("a tier has a track");
326	        let staying = best_of(
327	            &mut candidates
328	                .iter()
329	                .copied()
330	                .filter(|&(n, _)| Some(identity(n)) == primary),
331	        );
332	        let mut lost = false;
333	        let chosen = match staying {
334	            Some((stay, stay_score)) if !first_of_shot => {
335	                let meeting: Vec<(usize, f64)> = candidates
336	                    .iter()
337	                    .copied()
338	                    .filter(|&(n, s)| {
339	                        Some(identity(n)) != primary && s >= RIVAL_MARGIN * stay_score
340	                    })
341	                    .collect();
342	                rivals.retain(|(id, _)| meeting.iter().any(|&(n, _)| identity(n) == *id));
343	                for &(n, _) in &meeting {
344	                    if !rivals.iter().any(|(id, _)| *id == identity(n)) {
345	                        rivals.push((identity(n), sample.t));
346	                    }
347	                }
348	                let ready = best_of(&mut meeting.iter().copied().filter(|&(n, _)| {
349	                    rivals
350	                        .iter()
351	                        .any(|&(id, since)| id == identity(n) && sample.t - since >= RIVAL_HOLD)
352	                }));
353	                match ready {
354	                    Some((n, _)) => n,
355	                    None => stay,
356	                }
357	            }
358	            // The primary absent (VR-24 (c)): the best present track stands
359	            // in, the primary kept, until `LOSS_HOLD` has passed.
360	            None if !first_of_shot && primary.is_some() => {
361	                let since = *absent_since.get_or_insert(sample.t);
362	                lost = sample.t - since < LOSS_HOLD;
363	                best.0
364	            }
365	            _ => best.0,
366	        };
367	        if !lost {
368	            absent_since = None;
369	            if Some(identity(chosen)) != primary {
370	                primary = Some(identity(chosen));
371	                rivals.clear();
372	            }
373	        }
374	        let second = match tracks[chosen].kind {
375	            SubjectKind::Face | SubjectKind::Person => best_of(
376	                &mut candidates
377	                    .iter()
378	                    .copied()
379	                    .filter(|&(n, _)| identity(n) != identity(chosen)),
380	            )
381	            .and_then(|(n, _)| tracks[n].at(i)),
382	            SubjectKind::Salient => None,
383	        };
384	        out.push(Chosen {
385	            t: sample.t,
386	            kind: Some(tracks[chosen].kind),
387	            track: Some(tracks[chosen].id),
388	            subject: tracks[chosen].at(i),
389	            identity: Some(identity(chosen)),
390	            lost,
391	            second,
392	        });
393	    }
394	    out
395	}
396	//! A framing composed into a clip that already moves (road map
397	//! "creator-jobs" VR2b1, spec §11 VR-27): `reframe.rs`'s path F written as
398	//! the clip's base and actions AROUND the actions it already carries, and
399	//! `replace`'s strip. Pure; `edit_reframe.rs`'s op decides and finishes.
400	//!
401	//! **Composition** (VR-27 (b)). P(t) is the input clip's evaluated
402	//! placement and F′ the scheduled path; a key `(k, dx, dy)` composes as
403	//! `scale′ = k·s`, `x′ = k·x + dx`, `y′ = k·y + dy`, raw. The base becomes
404	//! F′(0)∘P(0); an action end writes `video.{scale,x,y}` = F′(end)∘P(end)
405	//! when it names any of them (`null` included) or F′ changes across it.
406	//!
407	//! **Cuts first** (VR-27 (d)). A cut piece `[c − frame, c]` meeting an
408	//! action A naming `speed`, or ending past the clip, is CARRIED by A; any
409	//! other A is split at `c − frame` and `c`, each clamped into A, as
410	//! `edit_split.rs` narrows a straddled action (`state_patch`, `narrow_to`):
411	//! the head keeps A's id and curve, the cut piece is `linear`, the tail
412	//! keeps A's end and curve. So a linear A plays unchanged on every key,
413	//! volume included; an eased one is re-eased on each side (counted).
414	//!
415	//! **Then the moves** (VR-27 (c)), against the pieces: a move in no busy
416	//! span is its own action; one that overlaps a span is shifted earlier to
417	//! end at its start, by at most [`SHIFT_MAX`] and never before the
418	//! previous key or span; otherwise the first span's action CARRIES it — F′
419	//! holds to A's start and reaches the move's value at A's end along A's
420	//! curve, later moves inside A chaining into it.
421	//!
422	//! **Ids** (VR-27 (e)) are minted in time order for every new action and
423	//! tail; a clip's actions are written in start order. With no actions this
424	//! is VR2a2's writing to the byte: key 0 the base, one action per change.
425	
426	use std::collections::BTreeSet;
427	
428	use serde_json::{Map, Value};
429	
430	use crate::edit_split::{narrow_to, state_patch};
