515	impl Schedule {
516	    fn push(&mut self, t: Ticks, v: Value3, curve: Curve) {
517	        let key = FramingKey {
518	            t,
519	            scale: v.0,
520	            x: v.1,
521	            y: v.2,
522	            curve,
523	        };
524	        match self.keys.last_mut() {
525	            Some(last) if last.t >= t => *last = key,
526	            _ => self.keys.push(key),
527	        }
528	    }
529	
530	    fn value(&self) -> Value3 {
531	        let k = self.keys.last().expect("key 0");
532	        (k.scale, k.x, k.y)
533	    }
534	
535	    /// A segment of F (`from` → `to`, reaching `v`) as its own motion.
536	    fn own(&mut self, from: Ticks, to: Ticks, v: Value3, curve: Curve) {
537	        let hold = self.value();
538	        if from > self.keys.last().expect("key 0").t {
539	            self.push(from, hold, Curve::Linear);
540	        }
541	        self.push(to, v, curve);
542	        self.carrier = None;
543	    }
544	
545	    /// A segment carried by piece `i` (VR-27 (c)): hold to its start, reach
546	    /// `v` at its end along its curve; a later one inside it chains.
547	    fn carry(&mut self, i: usize, piece: &Piece, v: Value3) {
548	        if self.carrier != Some(i) {
549	            let hold = self.value();
550	            if piece.action.start > self.keys.last().expect("key 0").t {
551	                self.push(piece.action.start, hold, Curve::Linear);
552	            }
553	        }
554	        self.push(piece.end(), v, piece.action.curve);
555	        self.carrier = Some(i);
556	        self.carriers.insert(i);
557	    }
558	}
