564	/// `end`'s `video.{scale,x,y}` set to `v`, keeping every other key.
565	fn write_placement(end: &mut Value, v: Value3) {
566	    if !end.is_object() {
567	        *end = Value::Object(Map::new());
568	    }
569	    let Value::Object(end) = end else { return };
570	    let video = end
571	        .entry("video")
572	        .or_insert_with(|| Value::Object(Map::new()));
573	    if !video.is_object() {
574	        *video = Value::Object(Map::new());
575	    }
576	    if let Value::Object(video) = video {
577	        for (key, n) in PLACEMENT.iter().zip([v.0, v.1, v.2]) {
578	            video.insert((*key).to_string(), Value::from(n));
579	        }
580	    }
581	}
