583	impl Project {
584	    /// VR-27 (g): `clip` with `x`, `y` and `scale` removed from every end's
585	    /// `video` (a group left empty dropped, then an end left `{}`), and its
586	    /// base at the Fit placement of the cropped picture on the canvas.
587	    pub fn replaced(&self, clip: u32) -> Project {
588	        let mut next = self.clone();
589	        let Some(index) = next.clips.iter().position(|c| c.id == clip) else {
590	            return next;
591	        };
592	        let size = next.source_size(&next.clips[index]);
593	        let canvas = (f64::from(next.canvas.width), f64::from(next.canvas.height));
594	        let target = &mut next.clips[index];
595	        target.actions.retain_mut(|a| {
596	            let Value::Object(end) = &mut a.end else {
597	                return true;
598	            };
599	            if let Some(Value::Object(video)) = end.get_mut("video") {
600	                for key in PLACEMENT {
601	                    video.shift_remove(key);
602	                }
603	                if video.is_empty() {
604	                    end.shift_remove("video");
605	                }
606	            }
607	            !end.is_empty()
608	        });
609	        if let Some((mw, mh)) = size {
610	            let mut video = target.video.clone().unwrap_or_default();
611	            let crop = video.crop;
612	            let whole = ZoomRegion {
613	                x: 0.0,
614	                y: 0.0,
615	                width: mw - crop.l - crop.r,
616	                height: mh - crop.t - crop.b,
617	            };
618	            let scale = zoom_scale(canvas, &whole, ZoomFit::Fit, 0.0);
619	            let (x, y) = zoom_offset(&video, &whole, scale);
620	            (video.scale, video.x, video.y) = (scale, x, y);
621	            target.video = Some(video);
622	        }
623	        next
624	    }
