626	    /// `clip` with `path` composed into its base and actions (the module
627	    /// doc), and what composing counted.
628	    pub fn composed(&self, clip: u32, path: &FramingPath) -> (Project, Composed) {
629	        let mut next = self.clone();
630	        let (Some(index), Some(first)) = (
631	            next.clips.iter().position(|c| c.id == clip),
632	            path.keys.first(),
633	        ) else {
634	            return (next, Composed::default());
635	        };
636	        let original = self.clips[index].clone();
637	        let base = original.video.clone().unwrap_or_default();
638	        let placement = |t: Ticks| -> Value3 {
639	            let v = if original.actions.is_empty() {
640	                base.clone()
641	            } else {
642	                self.evaluate_clip(&original, t).video
643	            };
644	            (v.scale, v.x, v.y)
645	        };
646	        let mut pieces: Vec<Piece> = original
647	            .actions
648	            .iter()
649	            .map(|a| Piece {
650	                whole: a.end.get("speed").is_some()
651	                    || a.start.saturating_add(a.duration) > original.duration,
652	                action: a.clone(),
653	                fresh: false,
654	            })
655	            .collect();
656	        pieces.sort_by_key(|p| (p.action.start, p.action.id));
657	
658	        // F's segments: (from, to, value, curve, is a cut).
659	        let segments: Vec<(Ticks, Ticks, Value3, Curve, bool)> = path
660	            .keys
661	            .windows(2)
662	            .filter(|w| (w[0].scale, w[0].x, w[0].y) != (w[1].scale, w[1].x, w[1].y))
663	            .map(|w| {
664	                let (a, b) = (&w[0], &w[1]);
665	                (
666	                    a.t,
667	                    b.t,
668	                    (b.scale, b.x, b.y),
669	                    b.curve,
670	                    path.cuts.contains(&b.t),
671	                )
672	            })
673	            .collect();
674	
675	        // (d): every cut splits the action it lands in, first.
676	        let mut re_eased: BTreeSet<u32> = BTreeSet::new();
677	        for &(from, to, _, _, cut) in &segments {
678	            if !cut {
679	                continue;
680	            }
681	            let Some(i) = pieces.iter().position(|p| p.meets(from, to)) else {
682	                continue;
683	            };
684	            if pieces[i].whole {
685	                continue;
686	            }
687	            let a = pieces.remove(i);
688	            if a.action.curve != Curve::Linear {
689	                re_eased.insert(a.action.id);
690	            }
691	            let end_at = |t: Ticks| {
692	                narrow_to(
693	                    &state_patch(&self.evaluate_clip(&original, t)),
694	                    &a.action.end,
695	                    0,
696	                )
697	            };
698	            let (cf, ct) = (from.max(a.action.start), to.min(a.end()));
699	            let mut split = vec![
700	                (a.action.start, cf, a.action.curve, end_at(cf)),
701	                (cf, ct, Curve::Linear, end_at(ct)),
702	                (ct, a.end(), a.action.curve, a.action.end.clone()),
703	            ];
704	            split.retain(|&(s, e, _, _)| e > s);
705	            for (n, (start, end, curve, patch)) in split.into_iter().enumerate() {
706	                // The first written piece keeps A's id (the head, unless
707	                // A starts at the cut piece).
708	                let keeps = n == 0 && !a.fresh;
709	                pieces.push(Piece {
710	                    action: Action {
711	                        id: a.action.id,
712	                        start,
713	                        duration: end - start,
714	                        curve,
715	                        end: patch,
716	                    },
717	                    fresh: !keeps,
718	                    whole: false,
719	                });
720	            }
721	            pieces.sort_by_key(|p| (p.action.start, p.action.id));
722	        }
723	
724	        // (c): F′ in time order against the pieces.
725	        let mut f = Schedule {
726	            keys: vec![*first],
727	            carrier: None,
728	            carriers: BTreeSet::new(),
729	        };
730	        let mut own: Vec<Piece> = Vec::new();
731	        for &(from, to, v, curve, cut) in &segments {
732	            let Some(i) = pieces.iter().position(|p| p.meets(from, to)) else {
733	                f.own(from, to, v, curve);
734	                own.push(Piece::new(from, to - from, curve));
735	                continue;
736	            };
737	            let span = &pieces[i];
738	            let start = span.action.start;
739	            // A split cut piece (clamped into its action) is its own segment.
740	            if cut && !span.whole && start >= from && span.end() <= to {
741	                f.own(start, span.end(), v, curve);
742	                continue;
743	            }
744	            let shifted = start - (to - from);
745	            let previous = pieces
746	                .iter()
747	                .map(Piece::end)
748	                .filter(|&e| e <= start)
749	                .max()
750	                .unwrap_or(0)
751	                .max(f.keys.last().expect("key 0").t);
752	            if !cut && f.carrier != Some(i) && to - start <= SHIFT_MAX && shifted >= previous {
753	                f.own(shifted, start, v, curve);
754	                own.push(Piece::new(shifted, to - from, curve));
755	                continue;
756	            }
757	            f.carry(i, &pieces[i], v);
758	        }
759	
760	        // (b): the base and every end.
761	        let keys = f.keys;
762	        let mut carried = 0;
763	        for (i, piece) in pieces.iter_mut().enumerate() {
764	            let (s, e) = (piece.action.start, piece.end());
765	            let changes = at(&keys, s) != at(&keys, e);
766	            if changes && f.carriers.contains(&i) {
767	                carried += 1;
768	            }
769	            if changes || names_placement(&piece.action.end) {
770	                write_placement(&mut piece.action.end, compose(at(&keys, e), placement(e)));
771	            }
772	        }
773	        for piece in &mut own {
774	            let e = piece.end();
775	            write_placement(&mut piece.action.end, compose(at(&keys, e), placement(e)));
776	        }
777	        pieces.extend(own);
778	        // (e): fresh ids in time order, then the list in start order.
779	        pieces.sort_by_key(|p| p.action.start);
780	        for piece in pieces.iter_mut().filter(|p| p.fresh) {
781	            piece.action.id = next.allocate_id();
782	        }
783	        let (scale, x, y) = compose(at(&keys, 0), (base.scale, base.x, base.y));
784	        let target = &mut next.clips[index];
785	        target.video = Some(VideoProps {
786	            scale,
787	            x,
788	            y,
789	            ..base
790	        });
791	        target.actions = pieces.into_iter().map(|p| p.action).collect();
792	        let re_eased = re_eased.len();
793	        (next, Composed { re_eased, carried })
794	    }
795	}
796	//! A framing written as an edit (road map "creator-jobs" VR2a2 and VR2b1,
797	//! spec §11 VR-25…VR-27): `keep`'s rescale and the blurred backdrop behind
798	//! a `fit` span; the path itself is composed into the clip by
799	//! `reframe_compose.rs`. Pure: each answers a new project and
800	//! `edit_reframe.rs`'s op decides, checks and finishes.
801	//!
802	//! **`keep`** (VR-26, VR-27 (h)) is `set_canvas`'s rescale rule on the
803	//! clip's base and on every end key among `x`, `y` and `scale` that the end
804	//! names, through `rescale_video` itself.
805	//!
806	//! **The backdrop** (VR-25) is ONE copy of the original clip by
807	//! `add_blurred_background`'s builder, spanning the whole clip, because the
808	//! eases into and out of `fit` need it as much as the span itself. It goes
809	//! on the named track when that track can take it — unlocked, not a matte,
810	//! no clip intersecting the clip's span (touching is allowed) — and on a new
811	//! back-most track otherwise, so the op never refuses for a busy track. It
812	//! keeps the original's actions that name `speed`, each end narrowed to
813	//! `speed`, so a ramped clip's copy reads the same frames (VR-27 (i)).
814	
815	use serde_json::{Map, Value};
816	
817	use crate::edit_canvas::rescale_video;
818	use crate::model::{Action, Clip, Project, VideoProps};
819	
820	impl Project {
821	    /// `keep` (VR-26, VR-27 (h)): `set_canvas`'s rescale rule on the clip's
822	    /// base and on each `x`, `y` and `scale` an action's end names, from a
823	    /// `from` canvas to the current one.
824	    pub(crate) fn kept(&self, clip: u32, from: (u32, u32)) -> Project {
825	        let mut next = self.clone();
826	        let (w, h) = (
827	            f64::from(next.canvas.width) / f64::from(from.0),
828	            f64::from(next.canvas.height) / f64::from(from.1),
829	        );
830	        let Some(target) = next.clips.iter_mut().find(|c| c.id == clip) else {
831	            return next;
832	        };
833	        if !(w.is_finite() && h.is_finite()) {
834	            return next;
835	        }
836	        if let Some(video) = target.video.as_mut() {
837	            rescale_video(video, w, h);
838	        }
839	        for action in &mut target.actions {
840	            let Some(Value::Object(end)) = action.end.get_mut("video") else {
841	                continue;
842	            };
843	            let read = |key: &str| end.get(key).and_then(Value::as_f64);
844	            let mut video = VideoProps::default();
845	            video.scale = read("scale").unwrap_or(video.scale);
846	            video.x = read("x").unwrap_or(video.x);
847	            video.y = read("y").unwrap_or(video.y);
848	            rescale_video(&mut video, w, h);
849	            for (key, value) in [("scale", video.scale), ("x", video.x), ("y", video.y)] {
850	                if end.get(key).is_some_and(Value::is_number) {
851	                    end.insert(key.to_string(), Value::from(value));
852	                }
853	            }
854	        }
855	        next
856	    }
857	
858	    /// The backdrop of VR-25: one blurred copy of `original` on `backdrop`
859	    /// when that track can take it, else on a new back-most track (the
860	    /// module doc), with the original's speed actions (VR-27 (i)), their ids
861	    /// after the copy's. The op has refused a nest and a track not behind
862	    /// the clip's before calling, so the `Err` is `blurred_copy`'s own and
863	    /// not reached in practice.
864	    pub(crate) fn with_backdrop(self, original: &Clip, backdrop: u32) -> Result<Project, String> {
865	        let (start, end) = (original.start, original.start + original.duration);
866	        let free = self
867	            .track(backdrop)
868	            .is_some_and(|t| !t.locked && t.matte.is_none())
869	            && !self
870	                .clips
871	                .iter()
872	                .any(|c| c.track == backdrop && c.start < end && c.start + c.duration > start);
873	        let (mut next, track) = if free {
874	            (self, backdrop)
875	        } else {
876	            self.with_back_track()
877	        };
878	        let id = next.allocate_id();
879	        let mut copy = next.blurred_copy(original, id, track)?;
880	        for a in original.actions.iter() {
881	            let Some(speed) = a.end.get("speed") else {
882	                continue;
883	            };
884	            let mut end = Map::new();
885	            end.insert("speed".to_string(), speed.clone());
886	            copy.actions.push(Action {
887	                id: next.allocate_id(),
888	                end: Value::Object(end),
889	                ..a.clone()
890	            });
891	        }
892	        next.clips.push(copy);
893	        Ok(next)
894	    }
895	}
